import { useEffect, useState } from 'react';
import type { Workbox } from 'workbox-window';

let updateRequested = false;

/**
 * Registers the service worker (generated by scripts/build-sw.mjs) and shows
 * a non-blocking "update available" prompt. We never reload on our own: the
 * user may be mid-import or mid-slideshow.
 */
export function UpdatePrompt() {
  const [wb, setWb] = useState<Workbox>();
  const [waiting, setWaiting] = useState(false);
  const [offlineReady, setOfflineReady] = useState(false);

  useEffect(() => {
    if (!('serviceWorker' in navigator) || import.meta.env.DEV) return;
    let cancelled = false;
    let timer: ReturnType<typeof setInterval> | undefined;
    void import('workbox-window').then(({ Workbox }) => {
      if (cancelled) return;
      const w = new Workbox('/sw.js', { scope: '/' });
      w.addEventListener('waiting', () => setWaiting(true));
      w.addEventListener('installed', (e) => {
        if (!e.isUpdate) setOfflineReady(true);
      });
      // Reload only when the user asked for the update (first installs also fire 'controlling').
      w.addEventListener('controlling', () => {
        if (updateRequested) window.location.reload();
      });
      void w.register().catch(() => undefined);
      setWb(w);
      // Check for updates periodically while the app stays open.
      timer = setInterval(() => void w.update().catch(() => undefined), 60 * 60_000);
    });
    return () => {
      cancelled = true;
      clearInterval(timer);
    };
  }, []);

  useEffect(() => {
    if (!offlineReady) return;
    const t = setTimeout(() => setOfflineReady(false), 6000);
    return () => clearTimeout(t);
  }, [offlineReady]);

  if (waiting && wb) {
    return (
      <div className="toast" role="status">
        <span>A new version is available.</span>
        <button type="button" className="btn small primary" onClick={() => {
            updateRequested = true;
            wb.messageSkipWaiting();
          }}>
          Reload to update
        </button>
        <button type="button" className="btn small ghost" onClick={() => setWaiting(false)}>
          Later
        </button>
      </div>
    );
  }
  if (offlineReady) {
    return (
      <div className="toast" role="status" data-testid="offline-ready">
        Ready to work offline.
      </div>
    );
  }
  return null;
}
